import { strict as assert } from "node:assert";

export async function verify() {
  // Exercise 1: Map and filter without changing input
  {
    const original = [1, 2, 3, 4];
    const result = original.map((value) => value * 2).filter((value) => value > 4);
    assert.deepEqual(result, [6, 8]);
    assert.deepEqual(original, [1, 2, 3, 4]);
  }

// Exercise 2: Supply a reduction identity
{
  assert.equal(
    [].reduce((sum, value) => sum + value, 0),
    0,
  );
  assert.equal(
    [1, 2, 3].reduce((sum, value) => sum + value, 0),
    6,
  );
}

// Exercise 3: Expose default sort coercion
{
  assert.deepEqual([10, 2, 1].sort(), [1, 10, 2]);
  assert.deepEqual(
    [10, 2, 1].sort((a, b) => a - b),
    [1, 2, 10],
  );
}

// Exercise 4: Preserve an array while sorting
{
  const original = [3, 1, 2];
  const sorted = original.toSorted((a, b) => a - b);
  assert.deepEqual(sorted, [1, 2, 3]);
  assert.deepEqual(original, [3, 1, 2]);
}

// Exercise 5: Expose a shallow copy alias
{
  const original = [{ value: 1 }];
  const copy = [...original];
  copy[0].value = 9;
  assert.equal(original[0].value, 9);
  assert.notEqual(copy, original);
}

  // Exercise 6: Copy records for a specific edit
  {
    const original = [{ value: 1 }];
    const copy = original.map((row) => ({ ...row }));
    copy[0].value = 9;
    assert.equal(original[0].value, 1);
    assert.equal(copy[0].value, 9);
  }

  return { checks: 6, status: "passed" };
}

console.log(JSON.stringify(await verify()));

function lowerBound(values, target, trace = []) {
  let low = 0;
  let high = values.length;
  while (low < high) {
    const middle = low + Math.floor((high - low) / 2);
    trace.push([low, high, middle]);
    if (values[middle] < target) low = middle + 1;
    else high = middle;
  }
  return low;
}

function uniqueIndex(rows) {
  const index = new Map();
  for (const row of rows) {
    if (index.has(row.id)) throw new Error(`duplicate id ${row.id}`);
    index.set(row.id, row);
  }
  return index;
}

class MinHeap {
  values = [];
  push(value) {
    if (!Number.isFinite(value)) throw new TypeError("finite value required");
    const values = this.values;
    values.push(value);
    let index = values.length - 1;
    while (index > 0) {
      const parent = Math.floor((index - 1) / 2);
      if (values[parent] <= values[index]) break;
      [values[parent], values[index]] = [values[index], values[parent]];
      index = parent;
    }
  }

  pop() {
    const values = this.values;
    if (values.length === 0) return undefined;
    const minimum = values[0];
    const last = values.pop();
    if (values.length === 0) return minimum;
    values[0] = last;
    let index = 0;
    while (2 * index + 1 < values.length) {
      let child = 2 * index + 1;
      if (child + 1 < values.length && values[child + 1] < values[child]) child += 1;
      if (values[index] <= values[child]) break;
      [values[index], values[child]] = [values[child], values[index]];
      index = child;
    }
    return minimum;
  }
}

export async function verify() {
  // Exercise 1: Trace lower bound with duplicates
  {
    const trace = [];
    assert.equal(lowerBound([1, 4, 4, 8], 4, trace), 1);
    assert.deepEqual(trace, [
      [0, 4, 2],
      [0, 2, 1],
      [0, 1, 0],
    ]);
  }

  // Exercise 2: Use a heap for repeated minimum extraction
  {
    const heap = new MinHeap();
    for (const value of [5, 1, 3, 1]) heap.push(value);
    assert.deepEqual([heap.pop(), heap.pop(), heap.pop(), heap.pop()], [1, 1, 3, 5]);
    assert.equal(heap.pop(), undefined);
  }

  // Exercise 3: Cover empty and outside search boundaries
  {
    assert.equal(lowerBound([], 4), 0);
    assert.equal(lowerBound([2, 4, 6], 1), 0);
    assert.equal(lowerBound([2, 4, 6], 9), 3);
  }

  // Exercise 4: Measure comparisons without a timing claim
  {
    const values = Array.from({ length: 1024 }, (_, index) => index * 2);
    const trace = [];
    assert.equal(lowerBound(values, 1001, trace), 501);
    assert.ok(trace.length <= 11);
    assert.equal(values.includes(1001), false);
  }

  // Exercise 5: Reject duplicate index keys
  {
    const index = uniqueIndex([
      { id: "A", value: 7 },
      { id: "B", value: 9 },
    ]);
    assert.equal(index.get("A").value, 7);
    assert.throws(() => uniqueIndex([{ id: "A" }, { id: "A" }]), /duplicate/u);
  }

  // Exercise 6: Check the heap invariant after every update
  {
    const heap = new MinHeap();
    for (const value of [6, 5, 4, 3, 2, 1]) {
      heap.push(value);
      for (let index = 1; index < heap.values.length; index += 1) {
        assert.ok(heap.values[Math.floor((index - 1) / 2)] <= heap.values[index]);
      }
    }
    assert.throws(() => heap.push(NaN), TypeError);
  }

  return { checks: 6, status: "passed" };
}

console.log(JSON.stringify(await verify()));

function parts(date) {
  const formatter = new Intl.DateTimeFormat("en-US", {
    timeZone: "America/New_York",
    hour: "2-digit",
    minute: "2-digit",
    hourCycle: "h23",
    timeZoneName: "longOffset",
  });
  return Object.fromEntries(formatter.formatToParts(date).map((part) => [part.type, part.value]));
}

function calendarDate(text) {
  if (typeof text !== "string" || !/^\d{4}-\d{2}-\d{2}$/u.test(text))
    throw new RangeError("YYYY-MM-DD required");
  const date = new Date(text + "T00:00:00.000Z");
  if (!Number.isFinite(date.getTime()) || date.toISOString().slice(0, 10) !== text)
    throw new RangeError("invalid calendar date");
  return text;
}

export async function verify() {
  // Exercise 1: Compare offset spellings of one instant
  {
    const utc = new Date("2024-01-01T00:00:00Z");
    const offset = new Date("2023-12-31T19:00:00-05:00");
    assert.equal(utc.getTime(), offset.getTime());
    assert.equal(offset.toISOString(), "2024-01-01T00:00:00.000Z");
  }

  // Exercise 2: Observe a spring-forward clock gap
  {
    const before = new Date("2024-03-10T06:30:00Z");
    const after = new Date("2024-03-10T07:30:00Z");
    assert.equal(parts(before).hour, "01");
    assert.equal(parts(after).hour, "03");
    assert.equal(after.getTime() - before.getTime(), 60 * 60 * 1000);
  }

// Exercise 3: Reject impossible or ambiguous calendar text
{
  assert.equal(calendarDate("2024-02-29"), "2024-02-29");
  for (const text of ["2023-02-29", "01/02/2024", "2024-13-01"])
    assert.throws(() => calendarDate(text), RangeError);
}

// Exercise 4: Distinguish repeated fall-back clock readings
{
  const first = new Date("2024-11-03T05:30:00Z");
  const second = new Date("2024-11-03T06:30:00Z");
  assert.equal(parts(first).hour, "01");
  assert.equal(parts(second).hour, "01");
  assert.equal(parts(first).minute, parts(second).minute);
  assert.notEqual(parts(first).timeZoneName, parts(second).timeZoneName);
  assert.equal(second.getTime() - first.getTime(), 3600000);
}

  // Exercise 5: Inspect locale number parts without parsing display text
  {
    const value = 1234.5;
    const us = new Intl.NumberFormat("en-US").formatToParts(value);
    const de = new Intl.NumberFormat("de-DE").formatToParts(value);
    assert.equal(us.find((part) => part.type === "decimal").value, ".");
    assert.equal(de.find((part) => part.type === "decimal").value, ",");
    assert.equal(value, 1234.5);
  }

  // Exercise 6: Reject invalid timestamp and timezone assumptions
  {
    const invalid = new Date("not an ISO instant");
    assert.equal(Number.isNaN(invalid.getTime()), true);
    assert.throws(() => invalid.toISOString(), RangeError);
    assert.throws(
      () => new Intl.DateTimeFormat("en-US", { timeZone: "Invalid/Nowhere" }),
      RangeError,
    );
  }

  return { checks: 6, status: "passed" };
}

console.log(JSON.stringify(await verify()));
